import { createPlayerIntentCandidateSchema, deterministicId, hashWorldJson, resolutionAuthority,
  type PlayerIntentAffordance, type PlayerSubmissionV2, type WorldHash, type WorldJsonObject } from '@harness-world/contracts'
import { currentEntityState, parsePlayerActionInput, type CompiledWorldManifest, type RulebookEvent, type RulebookResolver } from '@harness-world/kernel'
import type { PlayerInputJob } from '@harness-world/store-sqlite'
import { PlayerInputInterpreter } from './player-input.ts'
import type { PlayerIntentProfile, PreparedPlayerIntent } from './player-intent-worker.ts'

/** Called only after PlayerBinding authorization, on the head selected by the durable input FIFO. */
export function preparePlayerIntent(job: PlayerInputJob, manifest: CompiledWorldManifest, events: readonly RulebookEvent[],
  resolver: RulebookResolver, profile: PlayerIntentProfile | undefined, budget: number,
  manifestHash: WorldHash, asOfWorldSeq: number):
  PreparedPlayerIntent | { directSubmission: PlayerSubmissionV2 } | { clarification: string } {
  const actor = manifest.playerBindings.find(value => value.principalId === job.principalId)
  if (actor === undefined) throw new TypeError('player input lost its PlayerBinding')
  const input = job.input as WorldJsonObject
  const sourceText = input.text as string
  const context = { manifest, events, characterId: actor.characterId, manifestHash, asOfWorldSeq,
    resolutionAuthority: resolutionAuthority('player', 'manual_player_immediate') }
  const afforded = resolver.affordances(context)
  if (Object.hasOwn(input, 'action') || sourceText.startsWith('/')) {
    const explicit = Object.hasOwn(input, 'action') ? { status: 'resolved' as const, action: parsePlayerActionInput(input.action!) }
      : new PlayerInputInterpreter().interpret(sourceText, afforded)
    if (explicit.status === 'clarification_required') return { clarification: explicit.reason }
    // An explicit command carries no version of its own, so it takes the one the affordance it exercises
    // is offered at - the same rule the interpreted path follows.
    const offered = afforded.find(value => value.actionType === explicit.action.actionType)
    if (offered === undefined) return { clarification: 'action is not currently afforded' }
    const action = { ...explicit.action, actionVersion: offered.actionVersion, actorId: actor.characterId,
      actionId: deterministicId('action', { version: 'player-intent-action/v1', address: job.address, inputId: job.inputId, ordinal: 0 }) }
    const source = action.actionType === 'speak' ? (action.parameters as WorldJsonObject).text as string : sourceText
    return { directSubmission: { version: 'player-submission/v2', sourceText: source, sourceTextHash: hashWorldJson('player-source-text/v1', source),
      actions: [action], sourceSpans: [{ actionId: action.actionId, startUtf16: 0, endUtf16: source.length, text: source,
        kind: action.actionType === 'speak' ? 'speech' : 'action' }], interpretationProfile: 'explicit-player-command/v1',
      interpretationReceiptHash: hashWorldJson('explicit-player-command/v1', { input: job.input, action }) } }
  }
  if (profile === undefined) return { clarification: 'player_intent_provider_unavailable' }
  const choices: PlayerIntentAffordance[] = []
  for (const affordance of afforded) {
    // The version is the affordance's own, not this adapter's: a frozen world offers its interactions at
    // version 2 with a request that names a binding and a definition lock, and a world that adjudicates
    // them through a catalog offers version 1. Speech and movement are 1 either way.
    if (affordance.actionType === 'speak') {
      choices.push({ affordanceId: 'speak', actionType: 'speak', actionVersion: 1, parameters: {} })
      // A publication choice, not a world-effect verb. The Host fills its narration
      // exclusively from quoted player text; the interpreter cannot author it.
      choices.push({ affordanceId: 'narrate', actionType: 'speak', actionVersion: 1,
        parameters: { text: '', narration: '' } })
    }
    if (affordance.actionType === 'move') {
      for (const location of manifest.locations) {
        const parameters = { locationId: location.locationId }
        if (resolver.resolve({ ...context, actionId: 'action:affordance-only', action: { actionType: 'move', parameters } }).status === 'accepted') {
          choices.push({ affordanceId: deterministicId('intent-affordance', { actionType: 'move', parameters }), actionType: 'move', actionVersion: 1, parameters })
        }
      }
    }
    if (affordance.actionType === 'interact') {
      for (const interaction of affordance.interactions ?? []) {
        const { label: _, ...parameters } = interaction
        const offered = { actionType: 'interact' as const,
          actionVersion: affordance.actionVersion === 2 ? 2 as const : 1 as const, parameters }
        choices.push({ affordanceId: deterministicId('intent-affordance', { actionType: 'interact', parameters }), ...offered })
      }
    }
  }
  // Names only for characters already referenced by offered choices; no private context or remote roster.
  const referencedCharacters = new Set(choices.flatMap(choice => {
    const parameters = choice.parameters
    const recipient = (parameters.arguments as WorldJsonObject | undefined)?.recipientId
    const target = parameters.targetRef as WorldJsonObject | undefined
    return [...(typeof recipient === 'string' ? [recipient] : []),
      ...(target?.kind === 'character' && typeof target.id === 'string' ? [target.id] : [])]
  }))
  const characterNames = manifest.characters.filter(character => referencedCharacters.has(character.characterId))
    .map(character => ({ characterId: character.characterId, name: character.name }))
  const alreadyCustodial = manifest.entities.filter(entity => currentEntityState(events, entity.entityId)?.holderId === actor.characterId)
    .map(entity => entity.entityId)
  const binding = { address: job.address, inputId: job.inputId, actorId: actor.characterId, sourceText,
    affordances: choices, interpretationProfile: `${profile.providerId}/${profile.modelId}/${profile.version}`,
    interpretationReceiptHash: hashWorldJson('player-intent-unprepared/v1', job.inputId) }
  return { binding, profile, budgetAvailable: budget >= profile.maxOutputTokens,
    request: { version: 'player-intent-request/v2', manifestHash: hashWorldJson('compiled-world-manifest', manifest),
      prefixHash: hashWorldJson('player-intent-prefix/v1', events.map(event => ({ ...event }))),
      // The contract is the Host's own words to the interpreter. It asks for the player's words, not for
      // arithmetic: a model that states offsets gets them wrong often enough to lose the player a turn,
      // while a verbatim quote is something the Host can find and check itself.
      contract: 'Interpret only the player intent. Select exact affordances by their affordanceId. '
        + `Character names referenced by offered choices: ${JSON.stringify(characterNames)}. `
        + `Items already in the player's custody: ${JSON.stringify(alreadyCustodial)}. `
        + 'Distinguish what the player COMMUNICATES from what the player EXECUTES. '
        + 'A request, question or suggestion addressed to an NPC is the player speaking, not an action '
        + 'executed for that NPC. Imperatives, permission, delegation and asking someone to keep an item are communication. '
        + 'They do not mean the player has already handed it over. Preserve the speaker, addressee and requested actor '
        + 'in the speech quote. Select speak even if the requested NPC response has no interaction option. '
        + 'For example: "GPT，先不要说话，可以只用表情或手势回应我一下吗？" is speak; '
        + '"GLM，你愿意去工作区吗？" is speak, not a player move. The NPC decides whether and how to respond. '
        + "Use narrate for the player's own freely expressed posture, expression or other minor observable "
        + 'performance, even with no dialogue: "我有点尴尬地笑了笑" is narrate. It is not a claim of an adjudicated effect. '
        + 'For a player-executed controlled change, such as "我走到工作区" or "我把手机收进随身包由我保管", select the corresponding '
        + 'move/interact option. Do not hide unavailable or ambiguous controlled actions inside narrate or speak. '
        + 'Item interactions control custody/carrying assignment, not hand contact or legal ownership. '
        + 'base:take acquires custody; base:give transfers custody to another character; base:drop relinquishes '
        + 'personal custody and leaves the item at the location. Only select these for an intended custody change. '
        + 'Flipping pages, touching, sliding, briefly lifting to inspect then returning, or temporarily setting '
        + 'your own custodial item on a table are free narrate, without take/give/drop. '
        + 'Explicitly retaining custody while setting an item down means no drop. Taking an unassigned item '
        + 'into your travel bag to carry away means take; packing your already custodial item does not reacquire it. '
        + 'Only an explicit intended continuing custody change by the player warrants a custody interaction. '
        + 'Bare lifting, lifting to look, and setting down state physical handling; use narrate without inferring custody. '
        + 'Intending to carry an unassigned item away is take; handling or packing an already custodial item is not another take. '
        + 'If the exact intended item is unavailable, clarify; never choose a different item merely because its action is offered. '
        + "Do not invent another character's reaction or publish an asserted reaction as the player's performance. "
        + 'Copy exact source words into quotes, in source order, without rewriting or calculating offsets. '
        + 'Each speak or narrate publication takes one contiguous quote. At most two actions, at most one '
        + 'controlled world operation; a performance and dialogue may be two publications. '
        + 'For a performance followed by movement, put narrate before move. For example, '
        + '"我轻轻笑了笑，走进后室看看有没有锁。" can use narrate quote "我轻轻笑了笑" then '
        + 'move quote "走进后室看看有没有锁"; the latter expresses an intention to look, not a found result. '
        + 'Do not attach words before and after the move to one noncontiguous narrate quote, or omit a meaningful later clause. '
        + 'Use free narrate instead of encoding ordinary expressions as performance cues. '
        + "Only clarify when ambiguity changes an executed action/target, the player's own controlled action "
        + 'is unavailable, or the input cannot be interpreted reliably. A missing NPC response verb is not a reason to clarify.',
      sourceText, affordances: choices, responseSchema: createPlayerIntentCandidateSchema() } }
}

packages/application/src/prototype-chara:
import { characterVisibleItems } from './character-visible-items.ts'
import { randomUUID } from 'node:crypto'
import { brandId, resolutionAuthority, type CharacterId, type WorldAddress, type WorldEventDraft,
  type WorldJsonObject, type WorldJsonValue } from '@harness-world/contracts'
import { characterRelationObservations, currentCharacterLifecycle,
  type CompiledWorldManifest, type RulebookRegistry } from '@harness-world/kernel'
import { CognitionProjectionRebuilder, CharacterViewBuilder, CharacterRuntimeAvailabilityService, WorldStore, WriterLeaseService } from '@harness-world/store-sqlite'
import type { CognitiveMemoryService } from '@harness-world/memory'
import { SceneDecisionService } from './scene-decision.ts'
import { characterExecutionResult, expressionAfterExecution } from './character-execution-result.ts'

export interface PrototypeTurnRequest {
  readonly context: WorldJsonObject
  readonly continuation: boolean
  readonly canPerform?: boolean
  readonly result?: WorldJsonObject
}

export interface PrototypeTurnResult {
  readonly status: 'published' | 'abstained' | 'budget_exhausted' | 'interrupted' | 'failed'
  readonly calls: number
  readonly performResult?: WorldJsonObject
  readonly failure?: 'provider_failed' | 'invalid_output'
}

function object(value: unknown): WorldJsonObject {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) throw new TypeError('expected object')
  return value as WorldJsonObject
}

function keys(value: WorldJsonObject, allowed: readonly string[]): void {
  if (Object.keys(value).some(key => !allowed.includes(key))) throw new TypeError('unexpected decision field')
}

/** One isolated activation, not a scheduler. Call only on a branch with no unfinished Reaction Cycle.
 * Uses the existing Rulebook, atomic WorldStore commit, scene audiences and character observations.
 * Intermediate model work is ephemeral; a committed operation is never rolled back for a failed reply.
 */
export class PrototypeCharacterTurn {
  #busy = false
  readonly #manifest: CompiledWorldManifest
  readonly #manifestHash
  readonly #scene: SceneDecisionService
  readonly #view: CharacterViewBuilder

  constructor(private readonly options: {
    readonly address: WorldAddress
    readonly store: WorldStore
    readonly memory?: CognitiveMemoryService
    readonly leases: WriterLeaseService
    readonly availability: CharacterRuntimeAvailabilityService
    readonly rulebooks: RulebookRegistry
    readonly decide: (request: PrototypeTurnRequest, signal: AbortSignal) => Promise<unknown>
  }) {
    const stored = options.store.readManifest(options.address)
    if (stored === undefined || (stored.manifest as WorldJsonObject).schemaVersion !== 10) {
      throw new TypeError('single-turn prototype requires an activated v10 world')
    }
    this.#manifest = stored.manifest as CompiledWorldManifest
    this.#manifestHash = stored.manifestHash
    this.#scene = new SceneDecisionService(options.store, options.availability, 2)
    this.#view = new CharacterViewBuilder(options.store)
  }

  async run(characterId: CharacterId, options: { readonly signal?: AbortSignal; readonly maxCalls?: 1 | 2 | 3;
    readonly stimulus?: readonly WorldJsonObject[];
    readonly continuationOf?: { readonly actionId: string; readonly afterSeq?: number;
      readonly action: { readonly actionType: string; readonly parameters: WorldJsonValue } } } = {}): Promise<PrototypeTurnResult> {
    if (this.#busy) throw new Error('single-turn prototype is busy')
    if (this.options.store.activeReactionCycle(this.options.address) !== undefined) {
      throw new Error('finish the existing Reaction Cycle before using the isolated prototype')
    }
    if (!this.#manifest.characters.some(character => character.characterId === characterId)
      || this.#manifest.playerBindings.some(binding => binding.characterId === characterId)) {
      throw new TypeError('activation requires a declared NPC')
    }
    this.#busy = true
    const ownerId = `prototype-turn:${randomUUID()}`
    const signal = options.signal === undefined ? AbortSignal.timeout(120_000)
      : AbortSignal.any([options.signal, AbortSignal.timeout(120_000)])
    let lease: ReturnType<WriterLeaseService['acquire']> | undefined
    let calls = 0
    let performResult: WorldJsonObject | undefined
    let modelFailure: PrototypeTurnResult['failure']
    const done = (status: PrototypeTurnResult['status']): PrototypeTurnResult => ({ status, calls,
      ...(performResult === undefined ? {} : { performResult }) })
    try {
      lease = this.options.leases.acquire(this.options.address, ownerId, 180_000)
      if (options.continuationOf !== undefined) {
        const prior = this.options.store.readEvents(this.options.address).findLast(event => event.eventType === 'action.resolved'
          && event.seq > (options.continuationOf!.afterSeq ?? 0)
          && object(event.data).actionId === options.continuationOf!.actionId && object(event.data).actorId === characterId
          && object(event.data).actionType === options.continuationOf!.action.actionType)
        if (prior === undefined) return done('failed')
        const resolved = object(prior.data)
        performResult = { operationId: options.continuationOf.actionId, action: options.continuationOf.action,
          status: resolved.accepted === true ? 'accepted' : 'rejected', reason: resolved.reason ?? null, eventRefs: [prior.seq] }
      }
      const maxCalls = options.continuationOf === undefined ? (options.maxCalls ?? 2) : 2
      for (let step = options.continuationOf === undefined ? 0 : 1; step < maxCalls; step += 1) {
        signal.throwIfAborted()
        const canPerform = options.continuationOf === undefined && (step === 0 || (step === 1 && maxCalls === 3))
        const head = this.options.store.head(this.options.address)
        const history = this.options.store.readEvents(this.options.address, head.headSeq)
        if (currentCharacterLifecycle(history, characterId) !== 'active') return done('interrupted')
        const rules = this.options.rulebooks.resolve(this.#manifest.rulebook.rulebookId,
          this.#manifest.rulebook.version, ownerId, this.options.address)
        const ruleContext = { manifest: this.#manifest, manifestHash: this.#manifestHash,
          events: history, characterId, asOfWorldSeq: head.headSeq,
          resolutionAuthority: resolutionAuthority('agent', 'standard') }
        const view = this.#view.rebuildAt(this.options.address, characterId, head.headSeq)
        const scene = this.#scene.decideFromEvents(this.options.address, characterId, history, head.headSeq)
        const character = this.#manifest.characters.find(value => value.characterId === characterId)!
        const recalled = this.options.memory?.prepareStimulus({
          address: this.options.address, roundId: brandId(`${ownerId}:${step}:memory`, 'InteractionRoundId'),
          participantId: characterId, characterId, asOfWorldSeq: head.headSeq,
          stimulus: options.stimulus ?? [], sceneCharacterIds: scene.observerIds,
          correlationId: `prototype-memory:${ownerId}:${step}`,
        })
        const recentObservations = view.observations.toSorted((left, right) => left.sourceSeq - right.sourceSeq).slice(-16)
        const recentSelfObservations = view.selfObservations.slice(-8)
        const recentSourceSeqs = new Set([...recentObservations, ...recentSelfObservations]
          .map(record => record.sourceSeq))
        const olderMemories = recalled?.memoryRecall.filter(memory =>
          !recentSourceSeqs.has(memory.sourceMaxSeq) && !('projectionId' in object(memory.metadata)))
        // Do not copy scene member records or other characters' anchors into a model request.
        const context: WorldJsonObject = {
          character,
          stimulus: options.stimulus ?? [],
          ...(olderMemories === undefined ? {} : { memories: olderMemories }),
          cognition: new CognitionProjectionRebuilder(this.options.store).rebuildCharacterAt(this.options.address, characterId, head.headSeq),
          scene: { locationId: view.locationId, people: scene.observerIds.map(id => ({ characterId: id,
            name: this.#manifest.characters.find(value => value.characterId === id)?.name ?? id })) },
          observations: recentObservations.map(record => {
            const value = object(record.value)
            if (value.content === null || typeof value.content !== 'object' || Array.isArray(value.content)) return record
            const content = object(value.content)
            if (typeof content.reason !== 'string') return record
            const { reason, ...rest } = content
            const feedback = characterExecutionResult({ manifest: this.#manifest, events: history, actorId: characterId,
              action: { actionType: String(content.actionType), parameters: {} }, status: String(content.status), reason })
            return { ...record, value: { ...value, content: { ...rest, resultDescription: feedback.description! } } }
          }), selfObservations: recentSelfObservations,
          claims: view.claims, goals: view.goals,
          items: characterVisibleItems(this.#manifest, history, characterId, scene.observerIds),
          affordances: rules.affordances(ruleContext).filter(value => canPerform || value.actionType === 'speak')
            .map(value => ({ actionType: value.actionType,
              ...(value.destinations === undefined ? {} : { destinations: value.destinations }),
              ...(value.interactions === undefined ? {} : { interactions: value.interactions }) })),
        }
        calls += 1
        modelFailure = 'provider_failed'
        const visibleResult = performResult === undefined ? undefined : characterExecutionResult({
          manifest: this.#manifest, events: history, actorId: characterId,
          action: object(performResult.action) as { actionType: string; parameters: WorldJsonValue },
          status: String(performResult.status), reason: typeof performResult.reason === 'string' ? performResult.reason : null })
        const raw = await this.options.decide({ context, continuation: step !== 0, canPerform,
          ...(visibleResult === undefined ? {} : { result: { ...visibleResult,
            instruction: canPerform
              ? '你已看到上次执行的真实结果。还可以申请一次受控交互，或直接表达或 abstain；未执行的后续状态变化不能写成既成事实。'
              : expressionAfterExecution, action: performResult!.action! } }) }, signal)
        modelFailure = undefined
        signal.throwIfAborted()
        // A changed world means this output is stale, including a change while awaiting the model.
        if (this.options.store.head(this.options.address).headSeq !== head.headSeq) return done('interrupted')
        lease = this.options.leases.renew(this.options.address, ownerId, lease.fencingToken, 180_000)
        modelFailure = 'invalid_output'
        const decision = object(raw)
        if (decision.decision === 'abstain') {
          keys(decision, ['decision'])
          return done('abstained')
        }
        let action: { actionType: string; parameters: WorldJsonValue }
        if (decision.decision === 'publish') {
          keys(decision, ['decision', 'speech', 'narration', 'addresseeIds'])
          for (const key of ['speech', 'narration']) {
            if (decision[key] !== undefined && (typeof decision[key] !== 'string' || decision[key].length > 2000)) {
              throw new TypeError('expression must be a string of at most 2000 characters')
            }
          }
          const addresseeIds = decision.addresseeIds ?? []
          if (!Array.isArray(addresseeIds) || addresseeIds.some(id => typeof id !== 'string'
            || id === characterId || !scene.observerIds.includes(brandId(id, 'CharacterId')))) {
            throw new TypeError('addressee must be another visible character')
          }
          action = { actionType: 'speak', parameters: { text: decision.speech ?? '', narration: decision.narration ?? '',
            ...(addresseeIds.length === 0 ? {} : { scope: 'direct', addresseeIds }) } }
        } else if (decision.decision === 'perform' && canPerform) {
          keys(decision, ['decision', 'actionType', 'parameters'])
          if (decision.actionType !== 'move' && decision.actionType !== 'interact') throw new TypeError('unsupported operation')
          const parameters = object(decision.parameters)
          keys(parameters, decision.actionType === 'move' ? ['locationId']
            : ['targetRef', 'bindingId', 'definitionRef', 'arguments'])
          action = { actionType: decision.actionType, parameters }
        } else throw new TypeError('operation budget exhausted; publish or abstain only')
        modelFailure = undefined
        const roundId = brandId(`${ownerId}:${step}`, 'InteractionRoundId')
        const actionId = `${roundId}:action`
        const resolution = rules.resolve({ ...ruleContext, action, roundId, actionId })
        const events: WorldEventDraft[] = [...resolution.events]
        if (resolution.status === 'accepted' && action.actionType === 'move') {
          events.push(...this.#scene.transitionForMove(this.options.address, history, characterId,
            object(action.parameters).locationId as string, head.headSeq))
        }
        events.push({ eventType: 'action.resolved', eventVersion: 1, data: { roundId, actionId,
          participantId: ownerId, actorId: characterId, actionType: action.actionType,
          sourceRole: 'agent', order: 0, accepted: resolution.status === 'accepted', reason: resolution.reason ?? null } })
        const audience = this.#scene.audienceForAction(this.options.address, characterId, history, head.headSeq,
          { scope: resolution.observationScope?.scope ?? 'scene_public',
            ...(resolution.observationScope?.recipientIds === undefined ? {} : {
              recipientIds: resolution.observationScope.recipientIds.map(id => brandId(id, 'CharacterId')) }) })
        const speech = resolution.events.find(event => event.eventType === 'character.speak')
        const transfer = resolution.events.find(event => event.eventType === 'entity.transferred')
        const relations = characterRelationObservations(history, resolution.events)
        const movement = resolution.events.find(event => event.eventType === 'character.moved')
        const movementData = movement?.data as { readonly characterId: CharacterId;
          readonly fromLocationId: string | null; readonly toLocationId: string } | undefined
        // The same move reaches both scenes, but neither scene alone grants the whole route.
        const departureObservers = movement === undefined ? undefined : new Set(this.#scene
          .decideFromEvents(this.options.address, characterId, history, head.headSeq).observerIds)
        const arrivalObservers = movement === undefined ? undefined : new Set(this.#scene
          .decideFromEvents(this.options.address, characterId, [...history, ...events],
            head.headSeq + events.length).observerIds)
        const arrived = movement === undefined ? [] : this.#scene.audienceForAction(this.options.address,
          characterId, [...history, ...events], head.headSeq + events.length).fullContentCharacterIds
        const full = new Set([...audience.fullContentCharacterIds, ...arrived, characterId])
        const outbox = []
        for (const observerId of new Set([...full, ...audience.occurrenceOnlyCharacterIds])) {
          const seesDeparture = observerId === characterId || departureObservers?.has(observerId) === true
          const seesArrival = observerId === characterId || arrivalObservers?.has(observerId) === true
          const id = `${actionId}:observer:${observerId}`
          const content: WorldJsonObject = full.has(observerId) ? {
            actorId: characterId, actionType: action.actionType, status: resolution.status,
            resultDescription: String(characterExecutionResult({ manifest: this.#manifest, events: [...history, ...resolution.events], actorId: characterId,
              action, status: resolution.status, reason: resolution.reason ?? null }).description)
              .replaceAll('你', observerId === characterId ? '你' : '行动者'),
            ...(speech === undefined ? {} : { speech: speech.data }),
            ...(transfer === undefined ? {} : { interaction: transfer.data }),
            ...(movementData === undefined || (!seesDeparture && !seesArrival) ? {} : { movement: {
              characterId: movementData.characterId,
              ...(seesDeparture ? { fromLocationId: movementData.fromLocationId } : {}),
              ...(seesArrival ? { toLocationId: movementData.toLocationId } : {}),
            } }),
            ...(relations.length === 0 ? {} : { relations }),
          } : { actorId: characterId, actionType: 'private_interaction', status: resolution.status, contentVisibility: 'occurrence_only' }
          const value = { observerId, actionId, content }
          events.push({ eventType: 'observation.upsert', eventVersion: 1, data: { id, value } })
          const player = this.#manifest.playerBindings.find(binding => binding.characterId === observerId)
          if (player !== undefined) outbox.push({ deliveryId: brandId(`${id}:delivery`, 'DeliveryId'),
            sessionId: player.sessionId, payload: { observationType: 'prototype-character-turn', observationId: id, value }, critical: true })
        }
        events.push({ eventType: 'world.tick-advanced', eventVersion: 1, data: { tick: head.tick + 1, roundId } })
        await this.options.store.commitRound({ address: this.options.address,
          transactionId: brandId(`${roundId}:commit`, 'TransactionId'), roundId,
          expectedHeadSeq: head.headSeq, expectedTick: head.tick, nextTick: head.tick + 1,
          events, outbox, writerFencingToken: lease.fencingToken, correlationId: ownerId,
          // This experiment does not fabricate a legacy batch Authority or provider-replay receipt.
          authority: { actorId: characterId, actionId, action, status: resolution.status,
            reason: resolution.reason ?? null, resolutionAuthority: ruleContext.resolutionAuthority },
        })
        if (action.actionType === 'speak') return done(resolution.status === 'accepted' ? 'published' : 'failed')
        performResult = { operationId: actionId, action, status: resolution.status, reason: resolution.reason ?? null,
          eventRefs: resolution.events.map((_, index) => head.headSeq + index + 1) }
      }
      return done('budget_exhausted')
    } catch (error) {
      if (signal.aborted) return done('interrupted')
      // Storage, lease, context and Rulebook faults remain visible to the caller.
      if (modelFailure === undefined) throw error
      return { ...done('failed'), failure: modelFailure }
    } finally {
      if (lease !== undefined) this.options.leases.release(this.options.address, ownerId, lease.fencingToken)
      this.#busy = false
    }
  }
}

packages/contracts/src/player-submission:
import { ACTION_GROUP_CUES,
  type ActionGroupCue, type StepManifestation } from './action-group.ts'
import { assertProtocolString, type CharacterId } from './ids.ts'
import type { ActionRequest, WorldAddress } from './protocol.ts'
import { canonicalizeWorldJson, deterministicId, hashWorldJson, type WorldHash, type WorldJsonObject, type WorldJsonValue } from './world-json.ts'

export interface PlayerSourceSpanV1 extends WorldJsonObject {
  readonly actionId: string
  readonly startUtf16: number
  readonly endUtf16: number
  readonly text: string
  readonly kind: 'speech' | 'narration' | 'action'
}

export interface PlayerSubmissionV2 extends WorldJsonObject {
  readonly version: 'player-submission/v2'
  readonly sourceText: string
  readonly sourceTextHash: WorldHash
  readonly actions: readonly ActionRequest[]
  readonly sourceSpans: readonly PlayerSourceSpanV1[]
  readonly interpretationProfile: string
  readonly interpretationReceiptHash: WorldHash
}

/** Host freezes exact choices; speak alone derives its text from source spans. */
export interface PlayerIntentAffordance extends WorldJsonObject {
  readonly affordanceId: string
  readonly actionType: 'speak' | 'move' | 'interact'
  /**
   * The version of the operation this choice addresses. An interaction a world does not adjudicate
   * through a definition is 1, and a frozen one is 2 because its request names a binding and a
   * definition lock rather than a catalog entry. Speech and movement are always 1.
   */
  readonly actionVersion: 1 | 2
  readonly parameters: WorldJsonObject
  /**
   * The cues this choice's definition accepts, as a set: a player may state one of them and nothing else.
   * Absent means the choice cannot carry a step at all, which is a different answer from "it accepts one
   * and the player did not state it" and must stay distinguishable. Placement (whether a cue plays only
   * on success) and any role it names are the definition's business and are adjudicated where the step is
   * decided, exactly as they are for a model's step; this list only says what is worth stating.
   */
  readonly performances?: readonly ActionGroupCue[]
}

export interface PlayerIntentBinding {
  readonly address: WorldAddress
  readonly inputId: string
  readonly actorId: CharacterId
  readonly sourceText: string
  readonly interpretationProfile: string
  readonly interpretationReceiptHash: WorldHash
  readonly affordances: readonly PlayerIntentAffordance[]
}

const REASONS = ['none', 'ambiguous', 'not_afforded', 'unsupported'] as const

/**
 * Deliberately no actor, final ActionId, arbitrary parameters, or narration fields. V2 added the step a
 * player states for the interaction they chose, drawn from the same closed vocabulary and schema the model
 * is handed, so how the player does it is declared rather than narrated into a fact.
 *
 * V3 removes the offsets. A candidate says which words of the player's own text name each action, and the
 * Host locates them: a model asked to count UTF-16 units gets that arithmetic wrong - measured, repeatedly
 * - and a wrong offset is indistinguishable from a sentence nobody said, while a verbatim quote is
 * something the Host can check and place itself.
 */
export function createPlayerIntentCandidateSchema() {
  return {
    type: 'object', additionalProperties: false, required: ['version', 'decision', 'reason', 'actions'],
    properties: {
      version: { const: 'player-intent-candidate/v3' },
      decision: { enum: ['act', 'clarification_required'] },
      reason: { enum: REASONS },
      actions: { type: 'array', maxItems: 2, items: {
        type: 'object', additionalProperties: false, required: ['key', 'affordanceId', 'quotes'],
        properties: { key: { type: 'string', minLength: 1 }, affordanceId: { type: 'string', minLength: 1 },
          quotes: { type: 'array', minItems: 1, maxItems: 8, items: { type: 'string', minLength: 1 } } },
      } },
    },
  }
}

function object(value: unknown, keys: readonly string[]): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)
    || Object.keys(value).sort().join(',') !== [...keys].sort().join(',')) throw new TypeError('player intent has invalid fields')
  return value as Record<string, unknown>
}

function exactWithOptional(value: unknown, required: readonly string[], optional: readonly string[]): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) throw new TypeError('player intent has invalid fields')
  const keys = Object.keys(value)
  if (keys.some(key => !required.includes(key) && !optional.includes(key))
    || required.some(key => !keys.includes(key))) throw new TypeError('player intent has invalid fields')
  return value as Record<string, unknown>
}

/**
 * One list of step cues, from the closed vocabulary. A cue that names a voice or a gait is not one of
 * them: it names an action of its own, and an interaction is never its own step. A repeat inside one list
 * is refused rather than normalized, because the model-facing schema forbids it - a caller that sends one
 * ignored the schema it was handed.
 */
function cueList(value: unknown, maximum: number): readonly ActionGroupCue[] {
  if (!Array.isArray(value) || value.length > maximum) throw new TypeError('player intent cue list is invalid')
  const cues = value.map(cue => {
    if (typeof cue !== 'string' || !Object.hasOwn(ACTION_GROUP_CUES, cue)) throw new TypeError('unknown cue')
    if (ACTION_GROUP_CUES[cue as ActionGroupCue].actionType !== null) {
      throw new TypeError('an interaction step cannot state a voice or gait cue')
    }
    return cue as ActionGroupCue
  })
  if (new Set(cues).size !== cues.length) throw new TypeError('duplicate player intent cue')
  return cues
}

/** The cues one interaction choice accepts, as the Host declared them. */
function acceptedCues(choice: Record<string, unknown>): readonly ActionGroupCue[] {
  if (choice.performances === undefined) return []
  // Only a frozen interaction has a locked policy to accept anything: a catalog entry has no definition
  // behind it, so a list here would be a promise the world cannot keep.
  if (choice.actionType !== 'interact' || choice.actionVersion !== 2) {
    throw new TypeError('only a frozen interaction choice declares accepted cues')
  }
  return cueList(choice.performances, Object.keys(ACTION_GROUP_CUES).length)
}

/** The words one action names, as the Host will look them up in the player's own text. */
function quoteList(value: unknown): readonly string[] {
  if (!Array.isArray(value) || value.length < 1 || value.length > 8) {
    throw new TypeError('player intent action requires the words it names')
  }
  const quotes = value.map(raw => {
    if (typeof raw !== 'string' || raw.length === 0) throw new TypeError('player intent quote is invalid')
    return raw
  })
  // One quote twice states nothing the first did not, and the second could only match words already spent.
  if (new Set(quotes).size !== quotes.length) throw new TypeError('player intent quote is repeated')
  return quotes
}

function step(value: unknown): StepManifestation {
  const root = object(value, ['independent', 'onSuccess'])
  return { independent: cueList(root.independent, 8), onSuccess: cueList(root.onSuccess, 8) }
}

function text(value: unknown): string {
  if (typeof value !== 'string') throw new TypeError('player intent requires a string')
  return assertProtocolString(value, 'player intent identifier')
}

/**
 * The exact parameters of one interaction choice, by the version it addresses. A v1 choice names a
 * catalog entry; a frozen one names the binding and the definition lock it addresses, and both are
 * checked here so a model cannot reach a shape the world's own boundary would refuse later.
 */
function interactParameters(version: 1 | 2, value: unknown): void {
  if (version === 1) {
    const parameters = object(value, ['targetId', 'interactionId', 'arguments'])
    text(parameters.targetId)
    text(parameters.interactionId)
    // Exact dynamic choices (including give recipient) are supplied by the Host.
    arguments_(parameters.arguments)
    return
  }
  const parameters = object(value, ['targetRef', 'bindingId', 'definitionRef', 'arguments'])
  const targetRef = object(parameters.targetRef, ['kind', 'id'])
  if (!['entity', 'character', 'relation'].includes(targetRef.kind as string)) {
    throw new TypeError('player intent interaction target kind is unsupported')
  }
  text(targetRef.id)
  text(parameters.bindingId)
  const definitionRef = object(parameters.definitionRef, ['id', 'version'])
  text(definitionRef.id)
  if (!Number.isSafeInteger(definitionRef.version) || (definitionRef.version as number) < 1) {
    throw new TypeError('player intent interaction definition version must be a positive safe integer')
  }
  arguments_(parameters.arguments)
}

function arguments_(value: unknown): void {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new TypeError('player intent interaction arguments must be an object')
  }
}

/** A pure Host binding boundary, not admission or a substitute for Rulebook revalidation. */
export function bindPlayerIntentCandidate(value: unknown, binding: PlayerIntentBinding):
  | { readonly status: 'clarification_required'; readonly reason: 'ambiguous' | 'not_afforded' | 'unsupported' }
  | { readonly status: 'validated'; readonly submission: PlayerSubmissionV2 } {
  canonicalizeWorldJson(value as WorldJsonValue)
  canonicalizeWorldJson(binding as unknown as WorldJsonValue)
  text(binding.inputId)
  text(binding.actorId)
  text(binding.interpretationProfile)
  const address = object(binding.address, ['tenantId', 'worldId', 'branchId'])
  for (const id of Object.values(address)) text(id)
  if (typeof binding.sourceText !== 'string' || binding.sourceText.length === 0
    || !/^sha256:[0-9a-f]{64}$/u.test(binding.interpretationReceiptHash)) throw new TypeError('player intent source or receipt is invalid')
  const choices = new Map<string, { readonly choice: PlayerIntentAffordance; readonly accepted: readonly ActionGroupCue[] }>()
  for (const choice of binding.affordances) {
    const raw = exactWithOptional(choice, ['affordanceId', 'actionType', 'actionVersion', 'parameters'], ['performances'])
    text(choice.affordanceId)
    if (choices.has(choice.affordanceId)
      || !['speak', 'move', 'interact'].includes(choice.actionType)) throw new TypeError('player intent affordance is invalid')
    const version = choice.actionVersion
    // The version belongs to the action type: only a frozen interaction addresses anything above 1, and
    // it addresses exactly 2 - it names a binding and a definition lock, which is the frozen request.
    if (choice.actionType === 'interact' ? version !== 1 && version !== 2 : version !== 1) {
      throw new TypeError('player intent affordance version is unsupported')
    }
    if (choice.actionType === 'speak') {
      if (Object.hasOwn(choice.parameters, 'narration')) {
        const publication = object(choice.parameters, ['text', 'narration'])
        if (publication.text !== '' || publication.narration !== '') throw new TypeError('narration choice must be an empty publication template')
      } else object(choice.parameters, [])
    }
    if (choice.actionType === 'move') text(object(choice.parameters, ['locationId']).locationId)
    if (choice.actionType === 'interact') interactParameters(version, choice.parameters)
    choices.set(choice.affordanceId, { choice, accepted: acceptedCues(raw) })
  }
  const candidate = object(value, ['version', 'decision', 'reason', 'actions'])
  // V3 is the only readable version: the Host publishes exactly this schema in the request it dispatches, so
  // an older candidate is a caller that ignored the contract it was handed rather than a peer to tolerate.
  if (candidate.version !== 'player-intent-candidate/v3' || !REASONS.includes(candidate.reason as never)
    || !Array.isArray(candidate.actions)) throw new TypeError('player intent candidate is invalid')
  if (candidate.decision === 'clarification_required') {
    if (candidate.reason === 'none' || candidate.actions.length !== 0) {
      throw new TypeError('clarification cannot contain actions')
    }
    return { status: 'clarification_required', reason: candidate.reason as 'ambiguous' | 'not_afforded' | 'unsupported' }
  }
  if (candidate.decision !== 'act' || candidate.reason !== 'none' || candidate.actions.length < 1 || candidate.actions.length > 2) {
    throw new TypeError('player intent action group is invalid')
  }
  const keys: string[] = []
  let requiresClarification = false
  const chosen: { readonly key: string; readonly choice: PlayerIntentAffordance
    readonly performance: StepManifestation | undefined; readonly quotes: readonly string[] }[] = []
  for (const raw of candidate.actions) {
    const action = exactWithOptional(raw, ['key', 'affordanceId', 'quotes'], ['performance'])
    const key = text(action.key)
    const found = choices.get(text(action.affordanceId))
    if (keys.includes(key) || found === undefined) throw new TypeError('player intent action is not uniquely afforded')
    const performance = action.performance === undefined ? undefined : step(action.performance)
    // What the player actually wrote, named by the action it belongs to: finding these in the source is what
    // makes a candidate checkable rather than merely well-formed.
    const quotes = quoteList(action.quotes)
    // A step the choice does not accept is not quietly dropped - dropping it would do something the player
    // did not say - and it does not fail the action either: the player is asked again, which is the answer
    // this boundary already gives for an action that is not currently afforded. This covers a step stated
    // for an action that cannot carry one at all, because such a choice declares no accepted cues.
    if (performance !== undefined
      && ![...performance.independent, ...performance.onSuccess].every(cue => found.accepted.includes(cue))) {
      requiresClarification = true
    }
    keys.push(key)
    chosen.push({ key, choice: found.choice, performance, quotes })
  }
  const actions: ActionRequest[] = chosen.map((entry, ordinal) => ({
    actionId: deterministicId('action', { version: 'player-intent-action/v1', address: binding.address, inputId: binding.inputId, ordinal }),
    actorId: binding.actorId, actionType: entry.choice.actionType, actionVersion: entry.choice.actionVersion,
    // The step joins the request the same way the model's does: it is adjudicated by the definition the
    // choice names, against the policy that definition locked, and it never becomes part of the effect.
    parameters: entry.performance === undefined
      ? entry.choice.parameters : { ...entry.choice.parameters, performance: entry.performance },
  }))
  if (actions.filter(action => action.actionType !== 'speak').length > 1) {
    throw new TypeError('player input permits at most one world operation')
  }
  // The Host places each quote rather than being told where it is. Searching on from the previous one is
  // what keeps the actions in the order the player spoke them, and a quote nobody wrote is refused here
  // instead of becoming a span pointing at words that were never said.
  let previousEnd = 0
  const sourceSpans: PlayerSourceSpanV1[] = []
  for (const [ordinal, entry] of chosen.entries()) {
    const action = actions[ordinal]!
    for (const quote of entry.quotes) {
      const start = binding.sourceText.indexOf(quote, previousEnd)
      if (start < 0) {
        if (binding.sourceText.includes(quote)) throw new TypeError('player intent quote is out of source order')
        throw new TypeError('player intent quote is not in the player text')
      }
      previousEnd = start + quote.length
      sourceSpans.push({ actionId: action.actionId, startUtf16: start, endUtf16: previousEnd, text: quote,
        kind: action.actionType === 'speak' ? (Object.hasOwn(entry.choice.parameters, 'narration') ? 'narration' : 'speech') : 'action' })
    }
  }
  for (const action of actions) {
    if (action.actionType !== 'speak') continue
    const spans = sourceSpans.filter(span => span.actionId === action.actionId)
    // A speech is one contiguous quote: joining two of them would invent a sentence nobody said.
    if (spans.length !== 1) throw new TypeError('player speech requires one contiguous quote')
    actions[actions.indexOf(action)] = { ...action, parameters: spans[0]!.kind === 'narration'
      ? { text: '', narration: spans[0]!.text } : { text: spans[0]!.text } }
  }
  // A semantic clarification must not turn an otherwise malformed Provider response into a valid result.
  // Validate every action and source span first, then give the player-facing answer for an unoffered step.
  if (requiresClarification) return { status: 'clarification_required', reason: 'not_afforded' }
  const submission: PlayerSubmissionV2 = {
    version: 'player-submission/v2', sourceText: binding.sourceText,
    sourceTextHash: hashWorldJson('player-source-text/v1', binding.sourceText), actions, sourceSpans,
    interpretationProfile: binding.interpretationProfile, interpretationReceiptHash: binding.interpretationReceiptHash,
  }
  // Detach all selected parameters from mutable Host/Adapter references.
  return { status: 'validated', submission: JSON.parse(new TextDecoder().decode(canonicalizeWorldJson(submission))) as PlayerSubmissionV2 }
}

